// ToolCategoryId 道具の分類の id
type ToolCategoryId = TableId

// ToolGrade 道具のグレード。高いほど速く壊し多く得る
type ToolGrade = int

// TrailStep 上端から下端への小道と、部屋どうしの小道を引く段
type TrailStep struct {
	Id EntityID `json:"id"`

	Tile EntityID `json:"tile"`
}

// TreeStep 部屋から遠い床ほど木を置く段
type TreeStep struct {
	// Density 部屋から遠い床に木を置く確率
	Density Chance `json:"density"`

	Id EntityID `json:"id"`

	// LargeTreeChance 木の周りにも木を足す確率
	LargeTreeChance Chance `json:"largeTreeChance"`
}

// ViewDistance AI視界距離（タイル単位）
type ViewDistance = int

// Vitality 体力。HPに影響する
type Vitality = int

// WarpNextTriggerRaw 次階層ワープトリガー
type WarpNextTriggerRaw = map[string]interface{}

// WarpPrevTriggerRaw 前階層ワープトリガー
type WarpPrevTriggerRaw = map[string]interface{}

// WaterEffect 水がタイルの気温に足す補正
type WaterEffect struct {
	Id WaterExposure `json:"id"`

	TempModifier TileTempModifier `json:"tempModifier"`
}

// WaterExposure タイルが受ける水の影響
type WaterExposure string

// Defines values for WaterExposure.
const (
	Nearby    WaterExposure = "nearby"
	Submerged WaterExposure = "submerged"
)

// Valid indicates whether the value is a known member of the WaterExposure enum.
func (e WaterExposure) Valid() bool {
	switch e {
	case Nearby:
		return true
	case Submerged:
		return true
	default:
		return false
	}
}

// WaterExposureValues は WaterExposure の値を、スキーマに書いた順に返す。
func WaterExposureValues() []WaterExposure {
	return []WaterExposure{Nearby, Submerged}
}

// Wearable 装備可能設定
type Wearable struct {
	Defense ArmorDefense `json:"defense"`

	EquipmentCategory EquipmentCategory `json:"equipmentCategory"`

	InsulationCold InsulationCold `json:"insulationCold"`

	InsulationHeat InsulationHeat `json:"insulationHeat"`
}

// Weather 天候。遷移の粘りの距離は行の順でなく Go の WeatherKind の並びに依る
type Weather struct {
	Id WeatherId `json:"id"`

	Name EntityName `json:"name"`

	Seasons []WeatherSeasonWeight `json:"seasons"`

	Severity WeatherSeverity `json:"severity"`

	SpellTurnsMax SpellTurns `json:"spellTurnsMax"`

	SpellTurnsMin SpellTurns `json:"spellTurnsMin"`

	TempModifier WeatherTempModifier `json:"tempModifier"`

	VisionDelta WeatherVisionDelta `json:"visionDelta"`
}

// WeatherId 天候の種類
type WeatherId string

// Defines values for WeatherId.
const (
	Blizzard WeatherId = "blizzard"
	Clear    WeatherId = "clear"
	Cloudy   WeatherId = "cloudy"
	ColdSnap WeatherId = "cold_snap"
	Rain     WeatherId = "rain"
	Snow     WeatherId = "snow"
)

// Valid indicates whether the value is a known member of the WeatherId enum.
func (e WeatherId) Valid() bool {
	switch e {
	case Blizzard:
		return true
	case Clear:
		return true
	case Cloudy:
		return true
	case ColdSnap:
		return true
	case Rain:
		return true
	case Snow:
		return true
	default:
		return false
	}
}

// WeatherIdValues は WeatherId の値を、スキーマに書いた順に返す。
func WeatherIdValues() []WeatherId {
	return []WeatherId{Clear, Cloudy, Rain, Snow, Blizzard, ColdSnap}
}

// WeatherSeasonWeight 季節ごとの天候の出やすさ
type WeatherSeasonWeight struct {
	Id SeasonId `json:"id"`

	Weight EntryWeight `json:"weight"`
}

// WeatherSeverity 天候の寒さの厳しさ。奥地ほど厳しい天候を厚くし、冬と奥地で長引かせるのに使う
type WeatherSeverity = int

// WeatherTempModifier 天候による世界温度への加算。℃
type WeatherTempModifier = int

// WeatherVisionDelta 天候による視程レンジへの加算。タイル。負で狭くなる
type WeatherVisionDelta = int

// Weight 重量。単位付き文字列で指定する。例: "500 g" "2 kg" "1 mg"
type Weight = string

// WidenStep 床に2マス以上接する壁を床にして通路を広げる段
type WidenStep struct {
	Chance Chance `json:"chance"`

	Id EntityID `json:"id"`
}

